    fn signal_candidate_with_direction_evidence(
        direction_hint: Option<InterfaceSignalDirection>,
        direction_hint_conflicted: bool,
        graph_direction_hint: Option<InterfaceSignalDirection>,
        graph_direction_hint_conflicted: bool,
    ) -> FsmSignalCandidate {
        FsmSignalCandidate {
            signal_name: "DATA".to_string(),
            direction_hint,
            direction_hint_conflicted,
            graph_direction_hint,
            graph_direction_hint_conflicted,
            width_hint: Some(1),
            parametric_width_hint: None,
            width_hint_conflicted: false,
            supporting_canonical_ids: Vec::new(),
            mention_categories: Vec::new(),
            automation_confidence: AutomationConfidence::High,
        }
    }

    #[test]
    fn preferred_signal_direction_hint_is_graph_first_and_conflict_sticky() {
        let flat_only = signal_candidate_with_direction_evidence(
            Some(InterfaceSignalDirection::Input),
            false,
            None,
            false,
        );
        assert_eq!(
            super::preferred_signal_direction_hint(&flat_only),
            Some(InterfaceSignalDirection::Input)
        );

        let graph_only = signal_candidate_with_direction_evidence(
            None,
            false,
            Some(InterfaceSignalDirection::Output),
            false,
        );
        assert_eq!(
            super::preferred_signal_direction_hint(&graph_only),
            Some(InterfaceSignalDirection::Output)
        );

        let matching_flat_and_graph = signal_candidate_with_direction_evidence(
            Some(InterfaceSignalDirection::Output),
            false,
            Some(InterfaceSignalDirection::Output),
            false,
        );
        assert_eq!(
            super::preferred_signal_direction_hint(&matching_flat_and_graph),
            Some(InterfaceSignalDirection::Output)
        );

        let conflicting_flat = signal_candidate_with_direction_evidence(
            Some(InterfaceSignalDirection::Input),
            true,
            Some(InterfaceSignalDirection::Input),
            false,
        );
        assert_eq!(
            super::preferred_signal_direction_hint(&conflicting_flat),
            None
        );

        let conflicting_graph = signal_candidate_with_direction_evidence(
            Some(InterfaceSignalDirection::Input),
            false,
            Some(InterfaceSignalDirection::Input),
            true,
        );
        assert_eq!(
            super::preferred_signal_direction_hint(&conflicting_graph),
            None
        );

        let flat_graph_disagreement = signal_candidate_with_direction_evidence(
            Some(InterfaceSignalDirection::Input),
            false,
            Some(InterfaceSignalDirection::Output),
            false,
        );
        assert_eq!(
            super::preferred_signal_direction_hint(&flat_graph_disagreement),
            None
        );
    }

    #[test]
    fn top_port_direction_hint_merge_keeps_conflict_sticky() {
        let mut evidence = super::TopPortDirectionEvidence::new(None, AutomationConfidence::Low);

        assert_eq!(
            super::merge_top_port_direction_hint(&mut evidence, InterfaceSignalDirection::Input),
            None
        );
        assert_eq!(
            evidence.direction_hint,
            Some(InterfaceSignalDirection::Input)
        );
        assert!(!evidence.direction_conflicted);

        assert_eq!(
            super::merge_top_port_direction_hint(&mut evidence, InterfaceSignalDirection::Output),
            Some(InterfaceSignalDirection::Input)
        );
        assert_eq!(evidence.direction_hint, None);
        assert!(evidence.direction_conflicted);

        assert_eq!(
            super::merge_top_port_direction_hint(&mut evidence, InterfaceSignalDirection::Output),
            None
        );
        assert_eq!(
            super::merge_top_port_direction_hint(&mut evidence, InterfaceSignalDirection::Input),
            None
        );
        assert_eq!(evidence.direction_hint, None);
        assert!(evidence.direction_conflicted);
    }

    fn top_port_width_recovery(
        width: u32,
        evidence_description: &str,
    ) -> super::TopPortWidthRecovery {
        super::TopPortWidthRecovery {
            width_hint: WidthHint::Numeric(width),
            mention_category: "top_port",
            supporting_canonical_ids: vec![format!("width_{width}")],
            automation_confidence: AutomationConfidence::High,
            evidence_description: evidence_description.to_string(),
        }
    }

    #[test]
    fn top_port_width_evidence_merge_keeps_conflict_sticky() {
        let mut evidence = super::TopPortWidthEvidence::new(None, AutomationConfidence::Low);
        let mut blocking_reasons = Vec::new();
        let mut required_canonical_enrichments = std::collections::BTreeSet::new();

        super::merge_top_port_width_evidence(
            &mut evidence,
            "DATA",
            top_port_width_recovery(8, "First top port declaration"),
            &mut blocking_reasons,
            &mut required_canonical_enrichments,
        );
        assert_eq!(evidence.width_hint, Some(WidthHint::Numeric(8)));
        assert!(!evidence.width_conflicted);
        assert!(blocking_reasons.is_empty());

        super::merge_top_port_width_evidence(
            &mut evidence,
            "DATA",
            top_port_width_recovery(16, "Conflicting top port declaration"),
            &mut blocking_reasons,
            &mut required_canonical_enrichments,
        );
        assert_eq!(evidence.width_hint, None);
        assert!(evidence.width_conflicted);
        assert!(
            blocking_reasons.iter().any(|reason| reason.contains(
                "Conflicting top port declaration implies top port `DATA` has width `16`"
            ))
        );
        assert!(required_canonical_enrichments.contains(
            "resolve conflicting top boundary port width evidence before lowering `?top:name`"
        ));
        let blocking_reason_count_after_conflict = blocking_reasons.len();

        super::merge_top_port_width_evidence(
            &mut evidence,
            "DATA",
            top_port_width_recovery(16, "Later matching top port declaration"),
            &mut blocking_reasons,
            &mut required_canonical_enrichments,
        );
        assert_eq!(evidence.width_hint, None);
        assert!(evidence.width_conflicted);
        assert_eq!(blocking_reasons.len(), blocking_reason_count_after_conflict);
    }

    #[test]
    fn output_inventory_drive_check_skips_topology_linked_child_outputs() {
        let mut local_output = signal_candidate_with_direction_evidence(
            None,
            false,
            Some(InterfaceSignalDirection::Output),
            false,
        );
        local_output.signal_name = "LOCAL_OUT".to_string();

        let mut topology_output = signal_candidate_with_direction_evidence(
            None,
            false,
            Some(InterfaceSignalDirection::Output),
            false,
        );
        topology_output.signal_name = "LINKED_OUT".to_string();
        topology_output
            .mention_categories
            .push("module_topology_link".to_string());

        let mut blocking_reasons = Vec::new();
        let mut required_canonical_enrichments = std::collections::BTreeSet::new();

        super::validate_output_inventory_is_driven(
            &[local_output, topology_output],
            &std::collections::BTreeSet::new(),
            &mut blocking_reasons,
            &mut required_canonical_enrichments,
            "typed control action",
            "recover graph-backed child endpoint drives before lowering `.fsm`",
        );

        assert!(
            blocking_reasons
                .iter()
                .any(|reason| reason.contains("`LOCAL_OUT` is not driven"))
        );
        assert!(
            !blocking_reasons
                .iter()
                .any(|reason| reason.contains("`LINKED_OUT` is not driven"))
        );
        assert!(
            required_canonical_enrichments
                .contains("recover graph-backed child endpoint drives before lowering `.fsm`")
        );
    }

