    fn actor_port(
        actor_name: &str,
        signal_name: &str,
        direction: ActorRelativeDirection,
    ) -> ActorPortRecord {
        ActorPortRecord {
            actor_id: format!("actor_{actor_name}"),
            actor_name: actor_name.to_string(),
            signal_name: signal_name.to_string(),
            direction,
            relation_basis: Vec::new(),
            width_hint: None,
            source_statement_ids: vec![format!("graph_{actor_name}_{signal_name}")],
            automation_confidence: AutomationConfidence::High,
        }
    }

    fn actor_port_with_numeric_width(
        actor_name: &str,
        signal_name: &str,
        direction: ActorRelativeDirection,
        width: u32,
    ) -> ActorPortRecord {
        let mut port = actor_port(actor_name, signal_name, direction);
        port.width_hint = Some(WidthHint::Numeric(width));
        port
    }

    fn actor_port_with_parametric_width(
        actor_name: &str,
        signal_name: &str,
        direction: ActorRelativeDirection,
        width: &str,
    ) -> ActorPortRecord {
        let mut port = actor_port(actor_name, signal_name, direction);
        port.width_hint = Some(WidthHint::Parametric(width.to_string()));
        port
    }

    fn clear_explicit_module_direction_hints(intent_ir: &mut IntentIr) {
        for module in &mut intent_ir.explicit_modules {
            for interface in &mut module.interfaces {
                for signal in &mut interface.signal_records {
                    signal.direction_hint = None;
                }
            }
        }
    }

    fn clear_explicit_module_signal_shape_hints(intent_ir: &mut IntentIr, signal_names: &[&str]) {
        for module in &mut intent_ir.explicit_modules {
            for interface in &mut module.interfaces {
                for signal in &mut interface.signal_records {
                    if signal_names.contains(&signal.signal_name.as_str()) {
                        signal.direction_hint = None;
                        signal.width_hint = None;
                    }
                }
            }
        }
    }

    fn clear_direct_interface_direction_hints(intent_ir: &mut IntentIr) {
        for interface in &mut intent_ir.interfaces {
            for signal in &mut interface.signal_records {
                signal.direction_hint = None;
            }
        }
    }

    fn clear_direct_signal_shape_hints(intent_ir: &mut IntentIr, signal_names: &[&str]) {
        for interface in &mut intent_ir.interfaces {
            for signal in &mut interface.signal_records {
                if signal_names.contains(&signal.signal_name.as_str()) {
                    signal.direction_hint = None;
                    signal.width_hint = None;
                }
            }
        }
    }

    fn remove_direct_signal_records(intent_ir: &mut IntentIr, signal_names: &[&str]) {
        for interface in &mut intent_ir.interfaces {
            interface
                .signal_records
                .retain(|signal| !signal_names.contains(&signal.signal_name.as_str()));
            interface
                .signals
                .retain(|signal_name| !signal_names.contains(&signal_name.as_str()));
        }
    }

    fn assert_renderable_system_contract_provenance(
        module: &FsmRenderableModule,
        system_contract_support_ids: &[String],
    ) {
        let system_contract = module
            .system_contract
            .as_ref()
            .expect("renderable module should keep system contract");
        assert_eq!(system_contract.clock_signal, "clk");
        assert_eq!(system_contract.reset_signal, "rst_n");
        assert!(
            system_contract_support_ids
                .iter()
                .any(|id| system_contract.supporting_statement_ids.contains(id))
        );
        assert_eq!(
            system_contract.automation_confidence,
            AutomationConfidence::High
        );
    }

    fn assert_renderable_init_assignment_provenance(
        module: &FsmRenderableModule,
        expected_assignments: &[InitAssignmentRecord],
    ) {
        let expected_by_target = expected_assignments
            .iter()
            .map(|assignment| (assignment.target_signal.as_str(), assignment))
            .collect::<BTreeMap<_, _>>();

        assert_eq!(module.init_assignments.len(), expected_assignments.len());
        for assignment in &module.init_assignments {
            let expected = expected_by_target
                .get(assignment.target_signal.as_str())
                .unwrap_or_else(|| {
                    panic!(
                        "renderable init assignment for {} should preserve a canonical source assignment",
                        assignment.target_signal
                    )
                });
            assert_eq!(&assignment.value, &expected.value);
            assert!(
                !assignment.supporting_statement_ids.is_empty(),
                "{} init assignment should retain support IDs",
                assignment.target_signal
            );
            assert_eq!(
                assignment.supporting_statement_ids,
                expected.supporting_statement_ids
            );
            assert_eq!(
                assignment.automation_confidence,
                expected.automation_confidence
            );
        }
    }

    fn assert_renderable_control_block_provenance(
        module: &FsmRenderableModule,
        expected_blocks: &[ControlBlockRecord],
    ) {
        let expected_by_id = expected_blocks
            .iter()
            .map(|block| (block.block_id.as_str(), block))
            .collect::<BTreeMap<_, _>>();
        let actual_blocks = module
            .blocks
            .iter()
            .chain(module.states.iter().flat_map(|state| state.blocks.iter()))
            .collect::<Vec<_>>();

        assert_eq!(actual_blocks.len(), expected_blocks.len());
        for block in actual_blocks {
            let expected = expected_by_id
                .get(block.block_id.as_str())
                .unwrap_or_else(|| {
                    panic!(
                        "renderable block {} should preserve a canonical source block",
                        block.block_id
                    )
                });
            assert!(
                !block.supporting_statement_ids.is_empty(),
                "{} should retain block support IDs",
                block.block_id
            );
            assert_eq!(
                block.supporting_statement_ids,
                expected.supporting_statement_ids
            );
            assert_eq!(block.automation_confidence, expected.automation_confidence);
            assert_eq!(block.branches.len(), expected.branches.len());

            let expected_branches = expected
                .branches
                .iter()
                .map(|branch| (branch.branch_id.as_str(), branch))
                .collect::<BTreeMap<_, _>>();
            for branch in &block.branches {
                let expected_branch = expected_branches
                    .get(branch.branch_id.as_str())
                    .unwrap_or_else(|| {
                        panic!(
                            "renderable branch {} should preserve a canonical source branch",
                            branch.branch_id
                        )
                    });
                assert!(
                    !branch.supporting_statement_ids.is_empty(),
                    "{} should retain branch support IDs",
                    branch.branch_id
                );
                assert_eq!(
                    branch.supporting_statement_ids,
                    expected_branch.supporting_statement_ids
                );
                assert_eq!(
                    branch.automation_confidence,
                    expected_branch.automation_confidence
                );
            }
        }
    }

    fn assert_state_graph_candidates_provenance(
        state_candidates: &[FsmStateCandidate],
        transition_candidates: &[FsmTransitionCandidate],
        regular_states: &[RegularStateRecord],
        state_transitions: &[StateTransitionRecord],
    ) {
        let expected_states = regular_states
            .iter()
            .map(|state| (state.state_id.as_str(), state))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(state_candidates.len(), expected_states.len());
        for state in state_candidates {
            let expected = *expected_states
                .get(state.state_id.as_str())
                .unwrap_or_else(|| {
                    panic!(
                        "state candidate {} should preserve a canonical source state",
                        state.state_id
                    )
                });
            assert_eq!(&state.state_name, &expected.state_name);
            assert_eq!(state.is_initial, expected.is_initial);
            assert_eq!(state.declaration_order, expected.declaration_order);
            assert!(
                !state.supporting_canonical_ids.is_empty(),
                "{} should retain state support IDs",
                state.state_id
            );
            assert_eq!(
                state.supporting_canonical_ids,
                expected.supporting_statement_ids
            );
            assert_eq!(state.automation_confidence, expected.automation_confidence);
        }

        let expected_transitions = state_transitions
            .iter()
            .map(|transition| (transition.transition_id.as_str(), transition))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(transition_candidates.len(), expected_transitions.len());
        for transition in transition_candidates {
            let expected = *expected_transitions
                .get(transition.transition_id.as_str())
                .unwrap_or_else(|| {
                    panic!(
                        "transition candidate {} should preserve a canonical source transition",
                        transition.transition_id
                    )
                });
            assert_eq!(&transition.source_state, &expected.source_state);
            assert_eq!(&transition.target_state, &expected.target_state);
            assert_eq!(&transition.guard, &expected.guard);
            assert_eq!(transition.declaration_order, expected.declaration_order);
            assert!(
                !transition.supporting_canonical_ids.is_empty(),
                "{} should retain transition support IDs",
                transition.transition_id
            );
            assert_eq!(
                transition.supporting_canonical_ids,
                expected.supporting_statement_ids
            );
            assert_eq!(
                transition.automation_confidence,
                expected.automation_confidence
            );
        }
    }

    fn assert_state_graph_candidate_provenance(fsm: &FsmAdapterArtifact, intent_ir: &IntentIr) {
        assert_state_graph_candidates_provenance(
            &fsm.state_candidates,
            &fsm.transition_candidates,
            &intent_ir.regular_states,
            &intent_ir.state_transitions,
        );
    }

    fn assert_module_state_graph_candidate_provenance(
        module: &FsmExplicitModuleCandidate,
        intent_ir: &IntentIr,
    ) {
        let expected_module = intent_ir
            .explicit_modules
            .iter()
            .find(|candidate| candidate.module_name == module.module_name)
            .unwrap_or_else(|| {
                panic!(
                    "module candidate {} should preserve a canonical explicit module",
                    module.module_name
                )
            });
        assert_state_graph_candidates_provenance(
            &module.state_candidates,
            &module.transition_candidates,
            &expected_module.regular_states,
            &expected_module.state_transitions,
        );
    }

    fn assert_module_candidate_surface_provenance(
        module: &FsmExplicitModuleCandidate,
        expected_module: &ExplicitModuleRecord,
    ) {
        assert_eq!(module.module_name, expected_module.module_name);
        assert_eq!(module.declaration_order, expected_module.declaration_order);
        assert_eq!(
            module.root_kind_decision.selected_root_kind,
            FsmRootKind::Fsm
        );
        assert_eq!(
            module.root_kind_decision.deferred_root_kinds,
            vec![FsmRootKind::Top]
        );
        assert_eq!(
            module.root_kind_decision.automation_confidence,
            AutomationConfidence::High
        );
        assert!(
            module
                .root_kind_decision
                .rationale
                .contains("explicit regular-state facts")
        );
        assert_eq!(module.system_contract, expected_module.system_contract);
        assert_eq!(
            module.init_assignments.len(),
            expected_module.init_assignments.len()
        );
        for (actual, expected) in module
            .init_assignments
            .iter()
            .zip(expected_module.init_assignments.iter())
        {
            assert_eq!(&actual.target_signal, &expected.target_signal);
            assert_eq!(&actual.value, &expected.value);
            assert!(
                !actual.supporting_statement_ids.is_empty(),
                "{} module candidate init assignment should retain support IDs",
                actual.target_signal
            );
            assert_eq!(
                actual.supporting_statement_ids,
                expected.supporting_statement_ids
            );
            assert_eq!(actual.automation_confidence, expected.automation_confidence);
        }
    }

    fn assert_renderable_state_graph_provenance_from_records(
        module: &FsmRenderableModule,
        regular_states: &[RegularStateRecord],
        state_transitions: &[StateTransitionRecord],
    ) {
        let mut expected_states = regular_states.iter().collect::<Vec<_>>();
        expected_states.sort_by_key(|state| (!state.is_initial, state.declaration_order));
        assert_eq!(module.states.len(), expected_states.len());
        for (state, expected) in module.states.iter().zip(expected_states.iter()) {
            assert_eq!(&state.state_name, &expected.state_name);
            assert_eq!(state.is_initial, expected.is_initial);
        }

        let mut expected_transitions_by_source = BTreeMap::<&str, Vec<_>>::new();
        for transition in state_transitions {
            expected_transitions_by_source
                .entry(transition.source_state.as_str())
                .or_default()
                .push(transition);
        }
        for transitions in expected_transitions_by_source.values_mut() {
            transitions.sort_by_key(|transition| transition.declaration_order);
        }

        let actual_transition_count = module
            .states
            .iter()
            .map(|state| state.transitions.len())
            .sum::<usize>();
        assert_eq!(actual_transition_count, state_transitions.len());
        for state in &module.states {
            let expected_transitions = expected_transitions_by_source
                .get(state.state_name.as_str())
                .map(Vec::as_slice)
                .unwrap_or(&[]);
            assert_eq!(state.transitions.len(), expected_transitions.len());
            for (transition, expected) in state.transitions.iter().zip(expected_transitions.iter())
            {
                assert_eq!(&transition.transition_id, &expected.transition_id);
                assert_eq!(&transition.source_state, &expected.source_state);
                assert_eq!(&transition.target_state, &expected.target_state);
                assert_eq!(&transition.guard, &expected.guard);
                assert_eq!(transition.declaration_order, expected.declaration_order);
                assert!(
                    !transition.supporting_statement_ids.is_empty(),
                    "{} should retain renderable transition support IDs",
                    transition.transition_id
                );
                assert_eq!(
                    transition.supporting_statement_ids,
                    expected.supporting_statement_ids
                );
                assert_eq!(
                    transition.automation_confidence,
                    expected.automation_confidence
                );
            }
        }
    }

    fn assert_renderable_state_graph_provenance(
        module: &FsmRenderableModule,
        intent_ir: &IntentIr,
    ) {
        assert_renderable_state_graph_provenance_from_records(
            module,
            &intent_ir.regular_states,
            &intent_ir.state_transitions,
        );
    }

    fn assert_module_renderable_state_graph_provenance(
        module: &FsmExplicitModuleCandidate,
        intent_ir: &IntentIr,
    ) {
        let expected_module = intent_ir
            .explicit_modules
            .iter()
            .find(|candidate| candidate.module_name == module.module_name)
            .unwrap_or_else(|| {
                panic!(
                    "renderable module {} should preserve a canonical explicit module",
                    module.module_name
                )
            });
        let renderable_module = module
            .renderable_module
            .as_ref()
            .expect("renderable explicit module should carry a renderable module");
        assert_renderable_state_graph_provenance_from_records(
            renderable_module,
            &expected_module.regular_states,
            &expected_module.state_transitions,
        );
    }

    fn assert_renderable_document_state_graph_provenance(
        fsm: &FsmAdapterArtifact,
        intent_ir: &IntentIr,
    ) {
        let renderable_module = fsm
            .renderable_module
            .as_ref()
            .expect("renderable FSM should carry a renderable module");
        assert_renderable_state_graph_provenance(renderable_module, intent_ir);

        let renderable_document = fsm
            .renderable_document
            .as_ref()
            .expect("renderable FSM should carry a source document");
        assert!(renderable_document.top_root.is_none());
        assert_eq!(renderable_document.direct_roots.len(), 1);
        let direct_root = &renderable_document.direct_roots[0];
        assert_eq!(direct_root.root_kind, FsmRootKind::Fsm);
        assert_eq!(&direct_root.module, renderable_module);
        assert_renderable_state_graph_provenance(&direct_root.module, intent_ir);
    }

    fn assert_standalone_module_renderable_projection_provenance(
        fsm: &FsmAdapterArtifact,
        module: &FsmExplicitModuleCandidate,
        intent_ir: &IntentIr,
    ) {
        assert_module_state_graph_candidate_provenance(module, intent_ir);
        assert_module_renderable_state_graph_provenance(module, intent_ir);
        let expected_module = intent_ir
            .explicit_modules
            .iter()
            .find(|candidate| candidate.module_name == module.module_name)
            .expect("source explicit module should be present");
        assert_module_candidate_surface_provenance(module, expected_module);

        let renderable_module = module
            .renderable_module
            .as_ref()
            .expect("standalone explicit module should carry a renderable module");
        if let Some(system_contract) = expected_module.system_contract.as_ref() {
            assert_renderable_system_contract_provenance(
                renderable_module,
                &system_contract.supporting_statement_ids,
            );
        }
        assert_renderable_control_block_provenance(
            renderable_module,
            &expected_module.control_blocks,
        );
        assert_renderable_init_assignment_provenance(
            renderable_module,
            &expected_module.init_assignments,
        );
        assert_eq!(fsm.renderable_module.as_ref(), Some(renderable_module));
        let renderable_document = fsm
            .renderable_document
            .as_ref()
            .expect("standalone explicit module should carry a source document");
        assert!(renderable_document.top_root.is_none());
        assert_eq!(renderable_document.direct_roots.len(), 1);
        let direct_root = &renderable_document.direct_roots[0];
        assert_eq!(&direct_root.module_name, &module.module_name);
        assert_eq!(
            direct_root.root_kind,
            module.root_kind_decision.selected_root_kind
        );
        assert_eq!(&direct_root.module, renderable_module);
        assert_renderable_state_graph_provenance_from_records(
            &direct_root.module,
            &expected_module.regular_states,
            &expected_module.state_transitions,
        );
        if let Some(system_contract) = expected_module.system_contract.as_ref() {
            assert_renderable_system_contract_provenance(
                &direct_root.module,
                &system_contract.supporting_statement_ids,
            );
        }
        assert_renderable_control_block_provenance(
            &direct_root.module,
            &expected_module.control_blocks,
        );
        assert_renderable_init_assignment_provenance(
            &direct_root.module,
            &expected_module.init_assignments,
        );
    }

    fn set_direct_signal_direction_hint(
        intent_ir: &mut IntentIr,
        signal_name: &str,
        direction_hint: InterfaceSignalDirection,
    ) {
        for interface in &mut intent_ir.interfaces {
            for signal in &mut interface.signal_records {
                if signal.signal_name == signal_name {
                    signal.direction_hint = Some(direction_hint);
                }
            }
        }
    }

    fn set_direct_signal_width_hint(intent_ir: &mut IntentIr, signal_name: &str, width: u32) {
        for interface in &mut intent_ir.interfaces {
            for signal in &mut interface.signal_records {
                if signal.signal_name == signal_name {
                    signal.width_hint = Some(WidthHint::Numeric(width));
                }
            }
        }
    }

    fn build_missing_child_module_top_intent_ir(base: &Path) -> Result<IntentIr> {
        build_intent_ir_from_markdown(
            base,
            "missing_child_top.md",
            "# Missing Child Module Composition\nTop datapath.\n\nTop datapath port result_data is output width 8.\n\nTop datapath child producer uses module missing_module.\n",
        )
    }

    fn build_missing_initial_fsm_intent_ir(base: &Path) -> Result<IntentIr> {
        build_intent_ir_from_markdown(
            base,
            "missing_initial_fsm.md",
            "# Missing Initial FSM Control\nSignal clk is input width 1.\n\nSignal rst_n is input width 1.\n\nSignal GO is input width 1.\n\nSignal DONE is input width 1.\n\nSignal DATA_IN is input width 8.\n\nSignal ACC is output width 8.\n\nClock clk.\n\nReset rst_n is asynchronous active low.\n\nInit ACC = 8'0.\n\nState idle.\n\nState busy.\n\nBlock idle: ACC <- DATA_IN.\n\nTransition idle -> busy when GO.\n\nBlock busy: ACC <- DATA_IN.\n\nTransition busy -> idle when DONE.\n",
        )
    }

    fn build_unknown_target_fsm_intent_ir(base: &Path) -> Result<IntentIr> {
        build_intent_ir_from_markdown(
            base,
            "unknown_target_fsm.md",
            "# Unknown Transition Target FSM Control\nSignal clk is input width 1.\n\nSignal rst_n is input width 1.\n\nSignal GO is input width 1.\n\nSignal DATA_IN is input width 8.\n\nSignal ACC is output width 8.\n\nClock clk.\n\nReset rst_n is asynchronous active low.\n\nInit ACC = 8'0.\n\nState idle is initial.\n\nState busy.\n\nBlock idle: ACC <- DATA_IN.\n\nTransition idle -> missing_state when GO.\n\nBlock busy: ACC <- DATA_IN.\n",
        )
    }

    #[test]
    fn builds_blocked_dt_centric_fsm_adapter_artifact() -> Result<()> {
        let tempdir = tempdir()?;
        let intent_ir = build_handshake_intent_ir(tempdir.path())?;
        let artifact_base = tempdir.path().join("generated").join("adapters");

        let adapter = AdapterArtifact::build(
            &intent_ir.artifact_layout.intent_ir_path,
            AdapterTarget::Fsm,
            &artifact_base,
        )?;
        adapter.write_to_disk()?;

        assert_eq!(adapter.target, AdapterTarget::Fsm);
        assert_eq!(adapter.required_input_stage.as_str(), "intent_ir");
        assert_eq!(adapter.lowering_status.as_str(), "blocked");
        assert!(!adapter.adapter_identity.adapter_id.is_empty());
        assert!(adapter.adapter_identity.adapter_id.starts_with("adapter_fsm_"));
        assert!(!adapter.adapter_identity.summary.is_empty());
        assert!(adapter.adapter_identity.summary.contains("`.fsm`"));
        assert!(!adapter.document_identity.document_key.is_empty());
        assert!(!adapter.document_identity.display_name.is_empty());
        assert!(
            adapter
                .artifact_layout
                .adapter_artifact_path
                .ends_with("generated/adapters/fsm/handshake/adapter.json")
        );
        assert!(adapter.artifact_layout.emitted_target_path.is_none());
        let signal_inventory_residual = adapter
            .residual_decisions
            .iter()
            .find(|packet| packet.packet_id == "fsm_adapter_signal_inventory")
            .expect("blocked DT-centric artifact should surface signal guidance");
        assert_eq!(
            signal_inventory_residual.automation_confidence,
            AutomationConfidence::Low
        );
        assert!(
            signal_inventory_residual
                .why_unresolved
                .contains("render-critical signal roles")
        );
        assert!(
            signal_inventory_residual
                .candidate_interpretations
                .iter()
                .any(|interpretation| interpretation.interpretation_id
                    == "enrich_intent_ir_interface_inventory")
        );

        let fsm = adapter.fsm.expect("fsm artifact should be present");
        assert_eq!(fsm.root_kind_decision.selected_root_kind, FsmRootKind::Dt);
        assert_eq!(
            fsm.root_kind_decision.deferred_root_kinds,
            vec![FsmRootKind::Fsm, FsmRootKind::Top]
        );
        assert_eq!(
            fsm.root_kind_decision.automation_confidence,
            AutomationConfidence::Medium
        );
        assert!(
            fsm.root_kind_decision
                .rationale
                .contains("does not yet carry explicit regular-state facts")
        );
        assert!(!fsm.renderability.is_renderable);
        assert!(
            fsm.renderability
                .blocking_reasons
                .iter()
                .any(|reason| { reason.contains("standalone decision-tree control blocks") })
        );
        assert!(fsm
            .renderability
            .required_canonical_enrichments
            .iter()
            .any(|enrichment| enrichment
                == "promote canonical standalone control blocks before lowering a `?dt:name` root"));
        assert!(fsm.renderable_module.is_none());
        assert!(fsm.renderable_document.is_none());
        assert_eq!(fsm.decision_tree_candidates.len(), 1);
        let dt_candidate = fsm
            .decision_tree_candidates
            .iter()
            .find(|candidate| candidate.candidate_id == "dt_primary_intent_cone")
            .expect("decision-tree candidate should remain visible");
        assert_eq!(
            dt_candidate.automation_confidence,
            AutomationConfidence::Medium
        );
        assert!(!dt_candidate.summary.is_empty());
        assert!(
            fsm.signal_inventory
                .iter()
                .any(|signal| signal.signal_name == "READY")
        );
        assert!(
            fsm.signal_inventory
                .iter()
                .any(|signal| signal.signal_name == "VALID")
        );
        assert!(
            fs::metadata(
                artifact_base
                    .join("fsm")
                    .join("handshake")
                    .join("adapter.json")
            )
            .is_ok()
        );
        assert!(
            fs::metadata(
                artifact_base
                    .join("fsm")
                    .join("handshake")
                    .join("handshake.fsm")
            )
            .is_err()
        );

        Ok(())
    }

    #[test]
    fn builds_renderable_standalone_dt_fsm_adapter_artifact() -> Result<()> {
        let tempdir = tempdir()?;
        let intent_ir = build_explicit_control_intent_ir(tempdir.path())?;
        let artifact_base = tempdir.path().join("generated").join("adapters");

        let adapter = AdapterArtifact::build(
            &intent_ir.artifact_layout.intent_ir_path,
            AdapterTarget::Fsm,
            &artifact_base,
        )?;
        adapter.write_to_disk()?;

        assert_eq!(adapter.lowering_status.as_str(), "renderable");
        assert!(!adapter.adapter_identity.adapter_id.is_empty());
        assert!(!adapter.adapter_identity.summary.is_empty());
        assert!(!adapter.document_identity.document_key.is_empty());
        let emitted_target_path = adapter
            .artifact_layout
            .emitted_target_path
            .as_ref()
            .expect("renderable adapter should emit target text");
        let emitted_text = fs::read_to_string(emitted_target_path)?;
        let fsm = adapter.fsm.expect("fsm artifact should be present");

        assert!(fsm.renderability.is_renderable);
        assert!(fsm.renderability.blocking_reasons.is_empty());
        assert!(fsm.renderability.required_canonical_enrichments.is_empty());
        assert!(fsm.renderable_module.is_some());
        assert!(fsm.renderable_document.is_some());
        assert_eq!(fsm.root_kind_decision.selected_root_kind, FsmRootKind::Dt);
        assert_eq!(
            fsm.root_kind_decision.deferred_root_kinds,
            vec![FsmRootKind::Fsm, FsmRootKind::Top]
        );
        assert_eq!(
            fsm.root_kind_decision.automation_confidence,
            AutomationConfidence::Medium
        );
        assert!(
            fsm.root_kind_decision
                .rationale
                .contains("does not yet carry explicit regular-state facts")
        );
        assert_eq!(fsm.decision_tree_candidates.len(), 1);
        assert!(
            fsm.decision_tree_candidates
                .iter()
                .any(|candidate| candidate.candidate_id == "dt_primary_intent_cone")
        );
        for signal_name in ["DATA_IN", "DATA_OUT", "ZERO_FLAG"] {
            let signal = fsm
                .signal_inventory
                .iter()
                .find(|signal| signal.signal_name == signal_name)
                .unwrap_or_else(|| {
                    panic!("{signal_name} should stay in baseline signal inventory")
                });
            assert!(
                !signal.supporting_canonical_ids.is_empty(),
                "{signal_name} should retain canonical support ids"
            );
            assert_eq!(signal.automation_confidence, AutomationConfidence::High);
        }
        assert!(fsm.signal_inventory.iter().any(|signal| {
            signal.signal_name == "DATA_IN"
                && signal.width_hint == Some(8)
                && signal.direction_hint.is_some()
        }));
        assert!(emitted_text.contains("(?dt:comb_dt"));
        assert!(emitted_text.contains("(+size"));
        assert!(emitted_text.contains("(DATA_IN 8)"));
        assert!(emitted_text.contains("(DATA_OUT 8)"));
        assert!(emitted_text.contains("(ZERO_FLAG 1)"));
        assert!(emitted_text.contains("(-route_data"));
        assert!(emitted_text.contains("(DATA_OUT = DATA_IN)"));
        assert!(emitted_text.contains("(-flag_zero"));
        assert!(emitted_text.contains("(<DATA_IN==8'0"));
        assert!(emitted_text.contains("(ZERO_FLAG = 1)"));
        assert!(
            adapter
                .residual_decisions
                .iter()
                .all(|packet| packet.packet_id != "fsm_adapter_signal_inventory")
        );
        assert!(
            adapter
                .residual_decisions
                .iter()
                .all(|packet| packet.packet_id != "fsm_adapter_dt_action_graph")
        );

        Ok(())
    }

    #[test]
    fn standalone_dt_recovers_directions_from_unambiguous_actor_ports() -> Result<()> {
        let tempdir = tempdir()?;
        let mut intent_ir = build_explicit_control_intent_ir(tempdir.path())?;
        clear_direct_interface_direction_hints(&mut intent_ir);
        intent_ir.actor_ports = vec![
            actor_port("controller", "DATA_IN", ActorRelativeDirection::Input),
            actor_port("controller", "DATA_OUT", ActorRelativeDirection::Output),
            actor_port("controller", "ZERO_FLAG", ActorRelativeDirection::Output),
        ];
        intent_ir.write_to_disk()?;

        let artifact_base = tempdir.path().join("generated").join("adapters");
        let adapter = AdapterArtifact::build(
            &intent_ir.artifact_layout.intent_ir_path,
            AdapterTarget::Fsm,
            &artifact_base,
        )?;
        adapter.write_to_disk()?;

        assert_eq!(adapter.lowering_status.as_str(), "renderable");
        let emitted_target_path = adapter
            .artifact_layout
            .emitted_target_path
            .as_ref()
            .expect("graph-backed standalone adapter should emit target text");
        let emitted_text = fs::read_to_string(emitted_target_path)?;
        let fsm = adapter.fsm.expect("fsm artifact should be present");

        assert_eq!(fsm.root_kind_decision.selected_root_kind, FsmRootKind::Dt);
        assert_eq!(
            fsm.root_kind_decision.deferred_root_kinds,
            vec![FsmRootKind::Fsm, FsmRootKind::Top]
        );
        assert_eq!(
            fsm.root_kind_decision.automation_confidence,
            AutomationConfidence::Medium
        );
        assert!(
            fsm.root_kind_decision
                .rationale
                .contains("does not yet carry explicit regular-state facts")
        );
        assert!(fsm.renderability.is_renderable);
        assert!(fsm.renderability.blocking_reasons.is_empty());
        assert!(fsm.renderability.required_canonical_enrichments.is_empty());
        assert!(fsm.renderable_module.is_some());
        assert!(fsm.renderable_document.is_some());
        let data_in = fsm
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "DATA_IN")
            .expect("DATA_IN should stay in the direct signal inventory");
        let data_out = fsm
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "DATA_OUT")
            .expect("DATA_OUT should stay in the direct signal inventory");
        let zero_flag = fsm
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "ZERO_FLAG")
            .expect("ZERO_FLAG should stay in the direct signal inventory");

        assert_eq!(data_in.direction_hint, None);
        assert_eq!(
            data_in.graph_direction_hint,
            Some(InterfaceSignalDirection::Input)
        );
        assert_eq!(data_out.direction_hint, None);
        assert_eq!(
            data_out.graph_direction_hint,
            Some(InterfaceSignalDirection::Output)
        );
        assert_eq!(zero_flag.direction_hint, None);
        assert_eq!(
            zero_flag.graph_direction_hint,
            Some(InterfaceSignalDirection::Output)
        );
        for (signal, support_id) in [
            (data_in, "graph_controller_DATA_IN"),
            (data_out, "graph_controller_DATA_OUT"),
            (zero_flag, "graph_controller_ZERO_FLAG"),
        ] {
            assert!(
                signal
                    .mention_categories
                    .iter()
                    .any(|category| category == "actor_port")
            );
            assert!(
                signal
                    .supporting_canonical_ids
                    .iter()
                    .any(|id| id == support_id)
            );
            assert_eq!(signal.automation_confidence, AutomationConfidence::High);
        }
        let renderable_module = fsm
            .renderable_module
            .as_ref()
            .expect("graph-backed standalone DT should produce a renderable module");
        let renderable_document_module = fsm
            .renderable_document
            .as_ref()
            .and_then(|document| document.direct_roots.first())
            .map(|root| &root.module);
        assert_eq!(renderable_document_module, Some(renderable_module));
        for (signal_name, direction_hint, width) in [
            ("DATA_IN", InterfaceSignalDirection::Input, 8),
            ("DATA_OUT", InterfaceSignalDirection::Output, 8),
            ("ZERO_FLAG", InterfaceSignalDirection::Output, 1),
        ] {
            let size_entry = renderable_module
                .size_entries
                .iter()
                .find(|entry| entry.signal_name == signal_name)
                .unwrap_or_else(|| panic!("{signal_name} should have a renderable size entry"));
            assert_eq!(size_entry.direction_hint, direction_hint);
            assert_eq!(size_entry.width, width);
        }
        assert!(emitted_text.contains("(?dt:comb_dt"));
        assert!(emitted_text.contains("(DATA_OUT = DATA_IN)"));
        assert!(emitted_text.contains("(ZERO_FLAG = 1)"));
        assert!(
            adapter
                .residual_decisions
                .iter()
                .all(|packet| packet.packet_id != "fsm_adapter_signal_inventory")
        );

        Ok(())
    }

