    #[test]
    fn builds_renderable_structured_fsm_with_reset_blocks() -> Result<()> {
        let tempdir = tempdir()?;
        let intent_ir = build_explicit_reset_fsm_intent_ir(tempdir.path())?;
        let artifact_base = tempdir.path().join("generated").join("adapters");

        let adapter = AdapterArtifact::build(
            &intent_ir.artifact_layout.intent_ir_path,
            AdapterTarget::Fsm,
            &artifact_base,
        )?;
        adapter.write_to_disk()?;

        assert_eq!(adapter.lowering_status.as_str(), "renderable");
        let emitted_target_path = adapter
            .artifact_layout
            .emitted_target_path
            .as_ref()
            .expect("renderable adapter should emit target text");
        let emitted_text = fs::read_to_string(emitted_target_path)?;
        let fsm = adapter.fsm.expect("fsm artifact should be present");

        assert!(fsm.renderability.is_renderable);
        assert!(fsm.renderability.blocking_reasons.is_empty());
        assert!(fsm.renderability.required_canonical_enrichments.is_empty());
        assert_eq!(fsm.root_kind_decision.selected_root_kind, FsmRootKind::Fsm);
        assert_eq!(
            fsm.root_kind_decision.deferred_root_kinds,
            vec![FsmRootKind::Top]
        );
        assert_eq!(
            fsm.root_kind_decision.automation_confidence,
            AutomationConfidence::High
        );
        assert!(
            fsm.root_kind_decision
                .rationale
                .contains("carries explicit regular-state facts")
        );
        let system_contract = fsm
            .system_contract
            .as_ref()
            .expect("renderable FSM should carry a system contract");
        assert_eq!(
            system_contract.reset_polarity,
            SystemResetPolarity::ActiveLow
        );
        assert_eq!(
            system_contract.assertion_timing,
            SystemResetTimingRelation::AsynchronousToClock
        );
        assert_eq!(
            system_contract.release_timing,
            SystemResetTimingRelation::SynchronousToClock
        );
        assert_eq!(
            system_contract.target_kind,
            SystemResetTargetKind::DedicatedResetPin
        );
        let renderable_module = fsm
            .renderable_module
            .as_ref()
            .expect("reset-block FSM should retain a renderable module");
        let renderable_document_module = fsm
            .renderable_document
            .as_ref()
            .and_then(|document| document.direct_roots.first())
            .map(|root| &root.module)
            .expect("renderable source document should contain reset-block FSM root");
        assert_eq!(renderable_module.states.len(), 2);
        let idle = renderable_module
            .states
            .iter()
            .find(|state| state.state_name == "idle")
            .expect("idle state should remain renderable");
        assert!(idle.is_initial);
        assert!(idle
            .blocks
            .iter()
            .flat_map(|block| &block.branches)
            .flat_map(|branch| &branch.actions)
            .any(|action| matches!(action, ControlActionRecord::Transition { target_state } if target_state == "busy")));
        let busy = renderable_module
            .states
            .iter()
            .find(|state| state.state_name == "busy")
            .expect("busy state should remain renderable");
        assert!(!busy.is_initial);
        assert!(busy
            .blocks
            .iter()
            .flat_map(|block| &block.branches)
            .flat_map(|branch| &branch.actions)
            .any(|action| matches!(action, ControlActionRecord::Transition { target_state } if target_state == "idle")));
        assert!(
            renderable_module
                .blocks
                .iter()
                .any(|block| block.role == ControlBlockRole::ResetSynchronous)
        );
        assert!(
            renderable_module
                .blocks
                .iter()
                .any(|block| block.role == ControlBlockRole::ResetAsynchronous)
        );
        assert_renderable_control_block_provenance(renderable_module, &intent_ir.control_blocks);
        assert_renderable_control_block_provenance(
            renderable_document_module,
            &intent_ir.control_blocks,
        );
        for signal_name in ["clk", "rst_n", "GO", "ACC", "PULSE_OUT"] {
            let signal = fsm
                .signal_inventory
                .iter()
                .find(|signal| signal.signal_name == signal_name)
                .unwrap_or_else(|| {
                    panic!("{signal_name} should stay in reset-block FSM signal inventory")
                });
            assert!(
                !signal.supporting_canonical_ids.is_empty(),
                "{signal_name} should retain canonical support ids"
            );
            assert_eq!(signal.automation_confidence, AutomationConfidence::High);
        }
        assert!(emitted_text.contains("(?fsm:reset_fsm"));
        assert!(emitted_text.contains("(+system"));
        assert!(emitted_text.contains("(clock clk)"));
        assert!(emitted_text.contains("(asreset rst_n)"));
        assert!(emitted_text.contains("(:= ACC=8'0)"));
        assert!(emitted_text.contains("(-syncrst"));
        assert!(emitted_text.contains("(ACC <= 8'0)"));
        assert!(emitted_text.contains("(-asyncreset"));
        assert!(emitted_text.contains("(PULSE_OUT> = 0)"));
        assert!(emitted_text.contains("(idle"));
        assert!(emitted_text.contains("(busy"));
        assert!(emitted_text.contains("(<GO"));
        assert!(emitted_text.contains("(-> busy)"));
        assert!(emitted_text.contains("(-> idle)"));

        Ok(())
    }

    #[test]
    fn structured_fsm_preserves_graph_backed_system_signal_inventory() -> Result<()> {
        let tempdir = tempdir()?;
        let mut intent_ir = build_explicit_reset_fsm_intent_ir(tempdir.path())?;
        clear_direct_interface_direction_hints(&mut intent_ir);
        let system_contract_support_ids = intent_ir
            .system_contract
            .as_ref()
            .map(|system_contract| system_contract.supporting_statement_ids.clone())
            .expect("structured FSM system contract should be present");
        intent_ir.actor_ports = vec![
            actor_port("controller", "clk", ActorRelativeDirection::Input),
            actor_port("controller", "rst_n", ActorRelativeDirection::Input),
            actor_port("controller", "GO", ActorRelativeDirection::Input),
            actor_port("controller", "ACC", ActorRelativeDirection::Output),
            actor_port("controller", "PULSE_OUT", ActorRelativeDirection::Output),
        ];
        intent_ir.write_to_disk()?;

        let artifact_base = tempdir.path().join("generated").join("adapters");
        let adapter = AdapterArtifact::build(
            &intent_ir.artifact_layout.intent_ir_path,
            AdapterTarget::Fsm,
            &artifact_base,
        )?;
        adapter.write_to_disk()?;

        assert_eq!(adapter.lowering_status.as_str(), "renderable");
        let emitted_target_path = adapter
            .artifact_layout
            .emitted_target_path
            .as_ref()
            .expect("graph-backed structured FSM should emit target text");
        let emitted_text = fs::read_to_string(emitted_target_path)?;
        let fsm = adapter.fsm.expect("fsm artifact should be present");

        assert_eq!(fsm.root_kind_decision.selected_root_kind, FsmRootKind::Fsm);
        assert_eq!(
            fsm.root_kind_decision.deferred_root_kinds,
            vec![FsmRootKind::Top]
        );
        assert_eq!(
            fsm.root_kind_decision.automation_confidence,
            AutomationConfidence::High
        );
        assert!(
            fsm.root_kind_decision
                .rationale
                .contains("carries explicit regular-state facts")
        );
        let clk = fsm
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "clk")
            .expect("clock should remain in structured FSM signal inventory");
        let rst_n = fsm
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "rst_n")
            .expect("reset should remain in structured FSM signal inventory");
        let go = fsm
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "GO")
            .expect("guard input should remain in structured FSM signal inventory");
        let acc = fsm
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "ACC")
            .expect("state output should remain in structured FSM signal inventory");
        let pulse_out = fsm
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "PULSE_OUT")
            .expect("reset pulse output should remain in structured FSM signal inventory");
        let renderable_module = fsm
            .renderable_module
            .as_ref()
            .expect("graph-backed structured FSM should retain a renderable module");
        let renderable_document_module = fsm
            .renderable_document
            .as_ref()
            .and_then(|document| document.direct_roots.first())
            .map(|root| &root.module)
            .expect("renderable source document should contain structured FSM root");

        for (signal, support_id) in [
            (clk, "graph_controller_clk"),
            (rst_n, "graph_controller_rst_n"),
        ] {
            assert_eq!(signal.direction_hint, Some(InterfaceSignalDirection::Input));
            assert_eq!(
                signal.graph_direction_hint,
                Some(InterfaceSignalDirection::Input)
            );
            assert!(
                signal
                    .mention_categories
                    .iter()
                    .any(|category| category == "system_contract_signal")
            );
            assert!(
                signal
                    .mention_categories
                    .iter()
                    .any(|category| category == "actor_port")
            );
            assert!(
                signal
                    .supporting_canonical_ids
                    .iter()
                    .any(|id| id == support_id)
            );
            assert_eq!(signal.width_hint, Some(1));
            assert_eq!(signal.automation_confidence, AutomationConfidence::High);
        }
        for (signal, direction_hint, support_id, width) in [
            (
                go,
                InterfaceSignalDirection::Input,
                "graph_controller_GO",
                1,
            ),
            (
                acc,
                InterfaceSignalDirection::Output,
                "graph_controller_ACC",
                8,
            ),
            (
                pulse_out,
                InterfaceSignalDirection::Output,
                "graph_controller_PULSE_OUT",
                1,
            ),
        ] {
            assert_eq!(signal.direction_hint, None);
            assert_eq!(signal.graph_direction_hint, Some(direction_hint));
            assert!(
                signal
                    .mention_categories
                    .iter()
                    .any(|category| category == "actor_port")
            );
            assert!(
                signal
                    .supporting_canonical_ids
                    .iter()
                    .any(|id| id == support_id)
            );
            assert_eq!(signal.width_hint, Some(width));
            assert_eq!(signal.automation_confidence, AutomationConfidence::High);
        }
        assert_renderable_system_contract_provenance(
            renderable_module,
            &system_contract_support_ids,
        );
        assert_renderable_system_contract_provenance(
            renderable_document_module,
            &system_contract_support_ids,
        );
        assert!(fsm.renderability.is_renderable);
        assert!(fsm.renderability.blocking_reasons.is_empty());
        assert!(fsm.renderability.required_canonical_enrichments.is_empty());
        assert!(fsm.renderable_module.is_some());
        assert!(fsm.renderable_document.is_some());
        assert!(emitted_text.contains("(?fsm:reset_fsm"));
        assert!(emitted_text.contains("(+system"));
        assert!(emitted_text.contains("(clock clk)"));
        assert!(emitted_text.contains("(asreset rst_n)"));
        assert!(
            adapter
                .residual_decisions
                .iter()
                .all(|packet| packet.packet_id != "fsm_adapter_system_contract")
        );
        assert!(
            adapter
                .residual_decisions
                .iter()
                .all(|packet| packet.packet_id != "fsm_adapter_signal_inventory")
        );
        assert!(
            adapter
                .residual_decisions
                .iter()
                .all(|packet| packet.packet_id != "fsm_adapter_dt_action_graph")
        );

        Ok(())
    }
