    #[test]
    fn standalone_sequential_dt_blocks_system_contract_flat_graph_direction_disagreement()
    -> Result<()> {
        let tempdir = tempdir()?;
        let mut intent_ir = build_explicit_sequential_control_intent_ir(tempdir.path())?;
        intent_ir.actor_ports = vec![
            actor_port("controller", "clk", ActorRelativeDirection::Output),
            actor_port("controller", "rst_n", ActorRelativeDirection::Input),
            actor_port("controller", "DATA_IN", ActorRelativeDirection::Input),
            actor_port("controller", "ACC", ActorRelativeDirection::Output),
        ];
        intent_ir.write_to_disk()?;

        let artifact_base = tempdir.path().join("generated").join("adapters");
        let adapter = AdapterArtifact::build(
            &intent_ir.artifact_layout.intent_ir_path,
            AdapterTarget::Fsm,
            &artifact_base,
        )?;

        assert_eq!(adapter.lowering_status.as_str(), "blocked");
        assert!(adapter.artifact_layout.emitted_target_path.is_none());
        let fsm = adapter.fsm.expect("fsm artifact should be present");
        assert_eq!(fsm.root_kind_decision.selected_root_kind, FsmRootKind::Dt);
        assert_eq!(
            fsm.root_kind_decision.deferred_root_kinds,
            vec![FsmRootKind::Fsm, FsmRootKind::Top]
        );
        let clk = fsm
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "clk")
            .expect("clock should remain in the signal inventory");

        assert_eq!(clk.direction_hint, Some(InterfaceSignalDirection::Input));
        assert_eq!(
            clk.graph_direction_hint,
            Some(InterfaceSignalDirection::Output)
        );
        assert!(
            clk.mention_categories
                .iter()
                .any(|category| category == "system_contract_signal")
        );
        assert!(
            clk.mention_categories
                .iter()
                .any(|category| category == "actor_port")
        );
        assert!(
            clk.supporting_canonical_ids
                .iter()
                .any(|id| id == "graph_controller_clk")
        );
        assert_eq!(clk.automation_confidence, AutomationConfidence::High);
        assert!(!fsm.renderability.is_renderable);
        assert!(fsm.renderable_module.is_none());
        assert!(fsm.renderable_document.is_none());
        assert!(fsm.renderability.blocking_reasons.iter().any(|reason| {
            reason.contains(
                "clock signal `clk` has conflicting canonical and graph-backed direction evidence",
            )
        }));
        assert!(fsm
            .renderability
            .required_canonical_enrichments
            .iter()
            .any(|enrichment| enrichment
                == "resolve conflicting canonical and graph-backed system-signal direction evidence before lowering `.fsm` system contracts"));
        let system_contract_residual = adapter
            .residual_decisions
            .iter()
            .find(|packet| packet.packet_id == "fsm_adapter_system_contract")
            .expect("system contract flat/graph conflict should surface system guidance");
        assert_eq!(
            system_contract_residual.automation_confidence,
            AutomationConfidence::Low
        );
        assert!(
            system_contract_residual
                .why_unresolved
                .contains("explicit clock/reset facts")
        );
        assert!(
            system_contract_residual
                .candidate_interpretations
                .iter()
                .any(|interpretation| interpretation.interpretation_id
                    == "enrich_intent_ir_system_surface")
        );

        Ok(())
    }

