    #[test]
    fn top_composition_recovers_child_directions_from_actor_ports() -> Result<()> {
        let tempdir = tempdir()?;
        let mut intent_ir = build_explicit_top_composition_intent_ir(tempdir.path())?;
        clear_explicit_module_direction_hints(&mut intent_ir);
        let (
            producer_output_signal_support_ids,
            consumer_input_signal_support_ids,
            consumer_result_signal_support_ids,
        ) = {
            let producer_output_signal = intent_ir
                .explicit_modules
                .iter()
                .find(|module| module.module_name == "producer_core")
                .and_then(|module| {
                    module
                        .interfaces
                        .iter()
                        .flat_map(|interface| interface.signal_records.iter())
                        .find(|signal| signal.signal_name == "output_data")
                })
                .expect("producer output_data declaration should be present");
            let consumer_input_signal = intent_ir
                .explicit_modules
                .iter()
                .find(|module| module.module_name == "consumer_core")
                .and_then(|module| {
                    module
                        .interfaces
                        .iter()
                        .flat_map(|interface| interface.signal_records.iter())
                        .find(|signal| signal.signal_name == "input_data")
                })
                .expect("consumer input_data declaration should be present");
            let consumer_result_signal = intent_ir
                .explicit_modules
                .iter()
                .find(|module| module.module_name == "consumer_core")
                .and_then(|module| {
                    module
                        .interfaces
                        .iter()
                        .flat_map(|interface| interface.signal_records.iter())
                        .find(|signal| signal.signal_name == "result_data")
                })
                .expect("consumer result_data declaration should be present");
            for signal in [
                producer_output_signal,
                consumer_input_signal,
                consumer_result_signal,
            ] {
                assert_eq!(signal.direction_hint, None);
            }
            (
                producer_output_signal.supporting_statement_ids.clone(),
                consumer_input_signal.supporting_statement_ids.clone(),
                consumer_result_signal.supporting_statement_ids.clone(),
            )
        };
        intent_ir.actor_ports = vec![
            actor_port(
                "producer_core",
                "output_data",
                ActorRelativeDirection::Output,
            ),
            actor_port("consumer_core", "input_data", ActorRelativeDirection::Input),
            actor_port(
                "consumer_core",
                "result_data",
                ActorRelativeDirection::Output,
            ),
        ];
        let producer_output_support_ids = intent_ir
            .actor_ports
            .iter()
            .find(|port| port.actor_name == "producer_core" && port.signal_name == "output_data")
            .map(super::actor_port_supporting_ids)
            .expect("producer output actor-port support should be present");
        let consumer_input_support_ids = intent_ir
            .actor_ports
            .iter()
            .find(|port| port.actor_name == "consumer_core" && port.signal_name == "input_data")
            .map(super::actor_port_supporting_ids)
            .expect("consumer input actor-port support should be present");
        let consumer_result_support_ids = intent_ir
            .actor_ports
            .iter()
            .find(|port| port.actor_name == "consumer_core" && port.signal_name == "result_data")
            .map(super::actor_port_supporting_ids)
            .expect("consumer result actor-port support should be present");
        intent_ir.write_to_disk()?;

        let artifact_base = tempdir.path().join("generated").join("adapters");
        let adapter = AdapterArtifact::build(
            &intent_ir.artifact_layout.intent_ir_path,
            AdapterTarget::Fsm,
            &artifact_base,
        )?;
        adapter.write_to_disk()?;

        assert_eq!(adapter.lowering_status.as_str(), "renderable");
        let emitted_target_path = adapter
            .artifact_layout
            .emitted_target_path
            .as_ref()
            .expect("graph-backed top adapter should emit target text");
        let emitted_text = fs::read_to_string(emitted_target_path)?;
        let fsm = adapter.fsm.expect("fsm artifact should be present");

        assert_eq!(fsm.root_kind_decision.selected_root_kind, FsmRootKind::Top);
        assert_eq!(
            fsm.root_kind_decision.deferred_root_kinds,
            vec![FsmRootKind::Dt, FsmRootKind::Fsm]
        );
        assert_eq!(
            fsm.root_kind_decision.automation_confidence,
            AutomationConfidence::High
        );
        assert!(
            fsm.root_kind_decision
                .rationale
                .contains("carries explicit top ports")
        );

        let producer = fsm
            .module_candidates
            .iter()
            .find(|candidate| candidate.module_name == "producer_core")
            .expect("producer module candidate should exist");
        assert_eq!(
            producer.root_kind_decision.selected_root_kind,
            FsmRootKind::Dt
        );
        assert_eq!(
            producer.root_kind_decision.deferred_root_kinds,
            vec![FsmRootKind::Fsm, FsmRootKind::Top]
        );
        assert_eq!(
            producer.root_kind_decision.automation_confidence,
            AutomationConfidence::Medium
        );
        assert!(
            producer
                .root_kind_decision
                .rationale
                .contains("does not yet carry explicit regular-state facts")
        );
        let consumer = fsm
            .module_candidates
            .iter()
            .find(|candidate| candidate.module_name == "consumer_core")
            .expect("consumer module candidate should exist");
        assert_eq!(
            consumer.root_kind_decision.selected_root_kind,
            FsmRootKind::Dt
        );
        assert_eq!(
            consumer.root_kind_decision.deferred_root_kinds,
            vec![FsmRootKind::Fsm, FsmRootKind::Top]
        );
        assert_eq!(
            consumer.root_kind_decision.automation_confidence,
            AutomationConfidence::Medium
        );
        assert!(
            consumer
                .root_kind_decision
                .rationale
                .contains("does not yet carry explicit regular-state facts")
        );
        let output_data = producer
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "output_data")
            .expect("producer output_data should stay in the module inventory");
        let input_data = consumer
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "input_data")
            .expect("consumer input_data should stay in the module inventory");
        let result_data = consumer
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "result_data")
            .expect("consumer result_data should stay in the module inventory");

        assert_eq!(output_data.direction_hint, None);
        assert_eq!(
            output_data.graph_direction_hint,
            Some(InterfaceSignalDirection::Output)
        );
        assert!(
            output_data
                .mention_categories
                .iter()
                .any(|category| category == "actor_port")
        );
        assert_eq!(input_data.direction_hint, None);
        assert_eq!(
            input_data.graph_direction_hint,
            Some(InterfaceSignalDirection::Input)
        );
        assert_eq!(result_data.direction_hint, None);
        assert_eq!(
            result_data.graph_direction_hint,
            Some(InterfaceSignalDirection::Output)
        );
        for (signal, support_ids) in [
            (output_data, &producer_output_support_ids),
            (input_data, &consumer_input_support_ids),
            (result_data, &consumer_result_support_ids),
        ] {
            assert!(
                signal
                    .mention_categories
                    .iter()
                    .any(|category| category == "actor_port")
            );
            assert!(
                support_ids
                    .iter()
                    .any(|id| signal.supporting_canonical_ids.contains(id))
            );
            assert_eq!(signal.automation_confidence, AutomationConfidence::High);
        }
        for (signal, signal_support_ids) in [
            (output_data, &producer_output_signal_support_ids),
            (input_data, &consumer_input_signal_support_ids),
            (result_data, &consumer_result_signal_support_ids),
        ] {
            assert!(
                signal
                    .mention_categories
                    .iter()
                    .any(|category| category == "interface")
            );
            assert!(
                signal_support_ids
                    .iter()
                    .any(|id| signal.supporting_canonical_ids.contains(id))
            );
        }
        assert!(fsm.renderability.is_renderable);
        assert!(fsm.renderability.blocking_reasons.is_empty());
        assert!(fsm.renderability.required_canonical_enrichments.is_empty());
        assert!(fsm.renderable_module.is_none());
        assert!(fsm.renderable_document.is_some());
        let renderable_document = fsm
            .renderable_document
            .as_ref()
            .expect("renderable document should be present");
        assert!(
            renderable_document
                .direct_roots
                .iter()
                .any(|r| Some(&r.module) == producer.renderable_module.as_ref())
        );
        assert!(
            renderable_document
                .direct_roots
                .iter()
                .any(|r| Some(&r.module) == consumer.renderable_module.as_ref())
        );
        for (module, signal_name, direction_hint) in [
            (producer, "output_data", InterfaceSignalDirection::Output),
            (consumer, "input_data", InterfaceSignalDirection::Input),
            (consumer, "result_data", InterfaceSignalDirection::Output),
        ] {
            let renderable_module = module
                .renderable_module
                .as_ref()
                .unwrap_or_else(|| panic!("{} should be renderable", module.module_name));
            let size_entry = renderable_module
                .size_entries
                .iter()
                .find(|entry| entry.signal_name == signal_name)
                .unwrap_or_else(|| panic!("{signal_name} should have a renderable size entry"));
            assert_eq!(size_entry.direction_hint, direction_hint);
            assert_eq!(size_entry.width, 8);
        }
        assert!(emitted_text.contains("/producer.output_data/consumer.input_data/"));
        assert!(emitted_text.contains("/consumer.result_data/result_data/"));
        assert!(
            adapter
                .residual_decisions
                .iter()
                .all(|packet| packet.packet_id != "fsm_adapter_composition_topology")
        );

        Ok(())
    }

    #[test]
    fn top_composition_recovers_child_directions_from_link_topology() -> Result<()> {
        let tempdir = tempdir()?;
        let mut intent_ir = build_explicit_top_composition_intent_ir(tempdir.path())?;
        clear_explicit_module_direction_hints(&mut intent_ir);
        let (
            producer_output_signal_support_ids,
            consumer_input_signal_support_ids,
            consumer_result_signal_support_ids,
            producer_to_consumer_support_ids,
            consumer_to_top_support_ids,
        ) = {
            let explicit_top = intent_ir
                .explicit_tops
                .iter()
                .find(|top| top.top_name == "datapath")
                .expect("explicit top should be present");
            let producer_to_consumer_link = explicit_top
                .links
                .iter()
                .find(|link| {
                    link.source.instance_name.as_deref() == Some("producer")
                        && link.source.signal_name == "output_data"
                        && link.target.instance_name.as_deref() == Some("consumer")
                        && link.target.signal_name == "input_data"
                })
                .expect("producer to consumer topology link should be present");
            let consumer_to_top_link = explicit_top
                .links
                .iter()
                .find(|link| {
                    link.source.instance_name.as_deref() == Some("consumer")
                        && link.source.signal_name == "result_data"
                        && link.target.instance_name.is_none()
                        && link.target.signal_name == "result_data"
                })
                .expect("consumer to top topology link should be present");
            let producer_output_signal = intent_ir
                .explicit_modules
                .iter()
                .find(|module| module.module_name == "producer_core")
                .and_then(|module| {
                    module
                        .interfaces
                        .iter()
                        .flat_map(|interface| interface.signal_records.iter())
                        .find(|signal| signal.signal_name == "output_data")
                })
                .expect("producer output_data declaration should be present");
            let consumer_input_signal = intent_ir
                .explicit_modules
                .iter()
                .find(|module| module.module_name == "consumer_core")
                .and_then(|module| {
                    module
                        .interfaces
                        .iter()
                        .flat_map(|interface| interface.signal_records.iter())
                        .find(|signal| signal.signal_name == "input_data")
                })
                .expect("consumer input_data declaration should be present");
            let consumer_result_signal = intent_ir
                .explicit_modules
                .iter()
                .find(|module| module.module_name == "consumer_core")
                .and_then(|module| {
                    module
                        .interfaces
                        .iter()
                        .flat_map(|interface| interface.signal_records.iter())
                        .find(|signal| signal.signal_name == "result_data")
                })
                .expect("consumer result_data declaration should be present");
            for signal in [
                producer_output_signal,
                consumer_input_signal,
                consumer_result_signal,
            ] {
                assert_eq!(signal.direction_hint, None);
            }
            (
                producer_output_signal.supporting_statement_ids.clone(),
                consumer_input_signal.supporting_statement_ids.clone(),
                consumer_result_signal.supporting_statement_ids.clone(),
                super::explicit_top_link_supporting_ids(producer_to_consumer_link),
                super::explicit_top_link_supporting_ids(consumer_to_top_link),
            )
        };
        intent_ir.write_to_disk()?;

        let artifact_base = tempdir.path().join("generated").join("adapters");
        let adapter = AdapterArtifact::build(
            &intent_ir.artifact_layout.intent_ir_path,
            AdapterTarget::Fsm,
            &artifact_base,
        )?;
        adapter.write_to_disk()?;

        assert_eq!(adapter.lowering_status.as_str(), "renderable");
        let emitted_target_path = adapter
            .artifact_layout
            .emitted_target_path
            .as_ref()
            .expect("topology-backed top adapter should emit target text");
        let emitted_text = fs::read_to_string(emitted_target_path)?;
        let fsm = adapter.fsm.expect("fsm artifact should be present");

        assert_eq!(fsm.root_kind_decision.selected_root_kind, FsmRootKind::Top);
        assert_eq!(
            fsm.root_kind_decision.deferred_root_kinds,
            vec![FsmRootKind::Dt, FsmRootKind::Fsm]
        );
        assert_eq!(
            fsm.root_kind_decision.automation_confidence,
            AutomationConfidence::High
        );
        assert!(
            fsm.root_kind_decision
                .rationale
                .contains("carries explicit top ports")
        );

        let producer = fsm
            .module_candidates
            .iter()
            .find(|candidate| candidate.module_name == "producer_core")
            .expect("producer module candidate should exist");
        assert_eq!(
            producer.root_kind_decision.selected_root_kind,
            FsmRootKind::Dt
        );
        assert_eq!(
            producer.root_kind_decision.deferred_root_kinds,
            vec![FsmRootKind::Fsm, FsmRootKind::Top]
        );
        assert_eq!(
            producer.root_kind_decision.automation_confidence,
            AutomationConfidence::Medium
        );
        assert!(
            producer
                .root_kind_decision
                .rationale
                .contains("does not yet carry explicit regular-state facts")
        );
        let consumer = fsm
            .module_candidates
            .iter()
            .find(|candidate| candidate.module_name == "consumer_core")
            .expect("consumer module candidate should exist");

        let output_data = producer
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "output_data")
            .expect("producer output_data should stay in the module inventory");
        let input_data = consumer
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "input_data")
            .expect("consumer input_data should stay in the module inventory");
        let result_data = consumer
            .signal_inventory
            .iter()
            .find(|signal| signal.signal_name == "result_data")
            .expect("consumer result_data should stay in the module inventory");

        assert_eq!(output_data.direction_hint, None);
        assert_eq!(
            output_data.graph_direction_hint,
            Some(InterfaceSignalDirection::Output)
        );
        assert_eq!(input_data.direction_hint, None);
        assert_eq!(
            input_data.graph_direction_hint,
            Some(InterfaceSignalDirection::Input)
        );
        assert_eq!(result_data.direction_hint, None);
        assert_eq!(
            result_data.graph_direction_hint,
            Some(InterfaceSignalDirection::Output)
        );
        for signal in [output_data, input_data, result_data] {
            assert!(
                signal
                    .mention_categories
                    .iter()
                    .any(|category| category == "module_topology_link")
            );
            assert_eq!(signal.automation_confidence, AutomationConfidence::High);
        }
        for signal in [output_data, input_data] {
            assert!(
                producer_to_consumer_support_ids
                    .iter()
                    .any(|id| signal.supporting_canonical_ids.contains(id))
            );
        }
        for (signal, signal_support_ids) in [
            (output_data, &producer_output_signal_support_ids),
            (input_data, &consumer_input_signal_support_ids),
        ] {
            assert!(
                signal
                    .mention_categories
                    .iter()
                    .any(|category| category == "interface")
            );
            assert!(
                signal_support_ids
                    .iter()
                    .any(|id| signal.supporting_canonical_ids.contains(id))
            );
        }
        assert!(
            consumer_to_top_support_ids
                .iter()
                .any(|id| result_data.supporting_canonical_ids.contains(id))
        );
        assert!(
            consumer_result_signal_support_ids
                .iter()
                .any(|id| result_data.supporting_canonical_ids.contains(id))
        );
        assert!(producer.renderability.is_renderable);
        assert!(producer.renderability.blocking_reasons.is_empty());
        assert!(
            producer
                .renderability
                .required_canonical_enrichments
                .is_empty()
        );
        assert!(consumer.renderability.is_renderable);
        assert!(consumer.renderability.blocking_reasons.is_empty());
        assert!(
            consumer
                .renderability
                .required_canonical_enrichments
                .is_empty()
        );
        assert!(fsm.renderability.is_renderable);
        assert!(fsm.renderability.blocking_reasons.is_empty());
        assert!(fsm.renderability.required_canonical_enrichments.is_empty());
        assert!(fsm.renderable_module.is_none());
        assert!(fsm.renderable_document.is_some());
        let renderable_document = fsm
            .renderable_document
            .as_ref()
            .expect("renderable document should be present");
        assert!(
            renderable_document
                .direct_roots
                .iter()
                .any(|r| Some(&r.module) == producer.renderable_module.as_ref())
        );
        assert!(
            renderable_document
                .direct_roots
                .iter()
                .any(|r| Some(&r.module) == consumer.renderable_module.as_ref())
        );
        for (module, signal_name, direction_hint) in [
            (producer, "output_data", InterfaceSignalDirection::Output),
            (consumer, "input_data", InterfaceSignalDirection::Input),
            (consumer, "result_data", InterfaceSignalDirection::Output),
        ] {
            let renderable_module = module
                .renderable_module
                .as_ref()
                .unwrap_or_else(|| panic!("{} should be renderable", module.module_name));
            let size_entry = renderable_module
                .size_entries
                .iter()
                .find(|entry| entry.signal_name == signal_name)
                .unwrap_or_else(|| panic!("{signal_name} should have a renderable size entry"));
            assert_eq!(size_entry.direction_hint, direction_hint);
            assert_eq!(size_entry.width, 8);
        }
        assert!(emitted_text.contains("/producer.output_data/consumer.input_data/"));
        assert!(emitted_text.contains("/consumer.result_data/result_data/"));
        assert!(
            adapter
                .residual_decisions
                .iter()
                .all(|packet| packet.packet_id != "fsm_adapter_composition_topology")
        );

        Ok(())
    }

